/**
 * Generates supabase/seed.sql from src/data/seed.ts so the database and the
 * in-browser demo use identical fictional data.  Run: npx tsx scripts/generate-seed.ts
 */
import { writeFileSync } from 'node:fs'
import { BUILDINGS, CAMPUS, SEED_ISSUES, bySlug } from '../src/data/seed'
import { REWARDS } from '../src/data/rewards'

const q = (v: string | null | undefined) => (v == null ? 'null' : `'${v.replace(/'/g, "''")}'`)
const ago = (d: number) => `now() - interval '${d} days'`

const lines: string[] = [
  '-- GENERATED by scripts/generate-seed.ts — FICTIONAL demo data, not real campus conditions.',
  '-- Building positions follow a simplified hand-traced layout (geo_source = schematic); not surveyed.',
  '-- footprint_geojson is left empty: the app draws the schematic shapes until real footprints are imported.',
  'begin;',
  `insert into public.campuses (id, slug, name, center_latitude, center_longitude) values (${q(CAMPUS.id)}, ${q(CAMPUS.slug)}, ${q(CAMPUS.name)}, ${CAMPUS.centerLatitude}, ${CAMPUS.centerLongitude}) on conflict (id) do nothing;`,
]

for (const b of BUILDINGS) {
  lines.push(
    `insert into public.buildings (id, campus_id, slug, name, short_name, latitude, longitude, geo_source, height_m, floors) values (${q(b.id)}, ${q(b.campusId)}, ${q(b.slug)}, ${q(b.name)}, ${q(b.shortName)}, ${b.latitude}, ${b.longitude}, ${q(b.geoSource)}, ${b.heightM}, array[${b.floors.map(q).join(', ')}]) on conflict (id) do nothing;`,
  )
}

for (const s of SEED_ISSUES) {
  const b = bySlug(s.building)
  const id = `00000000-0000-4000-8002-${String(s.ref).padStart(12, '0')}`
  const resolvedAt = s.resolvedDaysAgo != null ? ago(s.resolvedDaysAgo) : 'null'
  const verifiedAt = s.verification === 'verified' ? ago(Math.max(0, s.daysAgo - 0.5)) : 'null'
  lines.push(
    `insert into public.issues (id, campus_id, building_id, floor, room, title, description, category, verification_status, repair_status, priority, is_sample, created_at, updated_at, verified_at, resolved_at) overriding system value values (${q(id)}, ${q(CAMPUS.id)}, ${q(b.id)}, ${q(s.floor)}, ${q(s.room)}, ${q(s.title)}, ${q(s.description)}, '${s.category}', '${s.verification}', '${s.repair}', '${s.priority}', true, ${ago(s.daysAgo)}, ${ago(s.resolvedDaysAgo ?? s.daysAgo)}, ${verifiedAt}, ${resolvedAt}) on conflict (id) do nothing;`,
  )
  for (const note of s.notes ?? []) {
    lines.push(
      `insert into public.issue_status_history (issue_id, kind, previous_status, new_status, note, created_at) values (${q(id)}, '${note.status ? 'repair' : 'note'}', null, ${q(note.status ?? null)}, ${q(note.note)}, ${ago(note.daysAgo)});`,
    )
  }
}
// issues.ref_number is an identity column; seed ids use ref 1001+ so move the sequence past them.
lines.push(`select setval(pg_get_serial_sequence('public.issues', 'ref_number'), 2000, false);`)

for (const r of REWARDS) {
  lines.push(
    `insert into public.rewards (id, title, description, points_required, image_key) values (${q(r.id)}, ${q(r.title)}, ${q(r.description)}, ${r.pointsRequired}, ${q(r.imageKey)}) on conflict (id) do nothing;`,
  )
}
lines.push('commit;', '')
writeFileSync(new URL('../supabase/seed.sql', import.meta.url), lines.join('\n'))
console.log(`seed.sql written: ${BUILDINGS.length} buildings, ${SEED_ISSUES.length} issues, ${REWARDS.length} rewards`)
